package studio.jiayu.neoagent;
public final class HealthRulesTest {
 static int passed;static void check(boolean b){if(!b)throw new AssertionError("Health check "+passed);passed++;}
 public static void main(String[] args){check(HealthRules.failure(true,500,"loading",40000,0).isEmpty());check(!HealthRules.failure(true,500,"loading",45001,0).isEmpty());check(HealthRules.failure(false,9000,"observing",90000,10000).isEmpty());check(HealthRules.failure(true,500,"deciding",74000,0).isEmpty());check(!HealthRules.failure(true,500,"deciding",75001,0).isEmpty());check(!HealthRules.failure(true,500,"observing",15001,0).isEmpty());check(HealthRules.failure(true,500,"observing",14999,0).isEmpty());check(!HealthRules.failure(true,3501,"waiting",0,0).isEmpty());check(HealthRules.failure(true,3500,"waiting",0,0).isEmpty());check(HealthRules.failure(true,500,"deciding",1000,5000).isEmpty());check(!HealthRules.failure(true,500,"deciding",1000,5001).isEmpty());check(!HealthRules.failure(true,500,"dispatching",10001,0).isEmpty());check(HealthRules.failure(true,500,"paused",900000,0).isEmpty());System.out.println("PASS: "+passed+" health checks; transient UI, pause, stage deadlines and lost heartbeat");}
}
